PROGRAM ST_P02_DELTAROBOT
VAR
    steg    : INT := 0;
    tmrCam  : TON;
    spdOk   : BOOL := FALSE;
    encOk   : BOOL := FALSE;
    xPickKvitterad  : BOOL := FALSE;
    xGreppBekraftat : BOOL := FALSE;
END_VAR

tmrCam(IN := EMG_OK AND NOT tmrCam.Q, PT := T#200ms);

spdOk := (ST110_CNV_SPD >= 0.20) AND (ST110_CNV_SPD <= 0.60);
encOk := (ST110_ENC_POS > 0.0) AND (ST110_ENC_POS <= 2500.0);

IF NOT EMG_OK THEN
    ST110_RB_PICK  := FALSE;
    ST110_VAC_ON   := FALSE;
    ST110_CAM_TRIG := FALSE;
    xPickKvitterad  := FALSE;
    xGreppBekraftat := FALSE;
    steg := 0;
ELSE
    ST110_CAM_TRIG := tmrCam.Q;
    CASE steg OF
        0:
            ST110_RB_PICK  := FALSE;
            ST110_VAC_ON   := FALSE;
            IF EMG_OK THEN
                steg := 1;
            END_IF;
        1:
            IF ST110_CAM_FOUND AND spdOk AND encOk THEN
                ST110_VAC_ON  := TRUE;
                ST110_RB_PICK := TRUE;
                xPickKvitterad  := FALSE;
                xGreppBekraftat := FALSE;
                steg := 2;
            END_IF;
        2:
            IF ST110_RB_BUSY THEN
                xPickKvitterad := TRUE;
            END_IF;
            IF ST110_VAC_OK THEN
                xGreppBekraftat := TRUE;
            END_IF;
            (* ST110_RB_DONE ensam sager bara att roboten kort klart banan.
               Utan ST110_RB_BUSY startade plockprogrammet aldrig, och utan
               ST110_VAC_OK fick sugkoppen aldrig grepp - kexet ligger da kvar
               pa bandet och nasta bild skulle rakna det tva ganger. *)
            IF ST110_RB_DONE AND xPickKvitterad AND xGreppBekraftat THEN
                ST110_RB_PICK := FALSE;
                ST110_VAC_ON  := FALSE;
                steg := 1;
            END_IF;
    END_CASE;
END_IF;
END_PROGRAM

